namespace Scheduling;

/// <summary>Finds the first calendar slot that fits a required duration.</summary>
public sealed class SlotFinder
{
    public Slot? FindFirstFit(Resource resource, TimeSpan duration, DateTime notBefore)
    {
        if (!CanSearch(resource, duration))
            return null;

        foreach (var slot in resource.Calendar)
        {
            if (IsSuitable(slot, duration, notBefore))
                return slot;
        }

        return null;
    }

    private static bool CanSearch(Resource resource, TimeSpan duration) =>
        resource.Calendar.Count != 0 && duration > TimeSpan.Zero;

    private static bool IsSuitable(Slot slot, TimeSpan duration, DateTime notBefore) =>
        slot.Start >= notBefore &&
        HasRequiredDuration(slot, duration) &&
        StartsDuringWorkingHours(slot) &&
        slot.End.Hour <= 20;

    private static bool HasRequiredDuration(Slot slot, TimeSpan duration) =>
        slot.End - slot.Start >= duration;

    private static bool StartsDuringWorkingHours(Slot slot) =>
        slot.Start.Hour >= 8 && slot.Start.Hour <= 18;
}
